@Injectable()
export class TournamentParticipantAdminService {
…
  private async resolveAddAthletes(
…
  ): Promise<ResolvedAddAthlete[]> {
…
    return this.resolveSelectedAthletes(
…
      managerId,
      dto.source,
      dto.players,
    );
  }

  private async resolveSelectedAthletes(
    tx: AppDbOrTx,
    tournament: AdminTournament,
    managerId: string,
    source: 'FRIENDS' | 'CLUB',
    players: AddAthletePlayerDto[],
  ): Promise<ResolvedAddAthlete[]> {
    const selectedIds = players.map((player) => player.userId!);
    const allowedIds = await this.getSourceUserIds(
      tx,
      tournament,
      managerId,
      source,
      selectedIds,
    );
    if (allowedIds.length !== selectedIds.length) {
      throw new ForbiddenException('Một hoặc nhiều ứng viên không còn đủ điều kiện.');
    }
    const rows = await tx
      .select({
        userId: schema.users.id,
        displayName: schema.profiles.fullName,
      })
      .from(schema.users)
      .leftJoin(schema.profiles, eq(schema.profiles.userId, schema.users.id))
      .where(
        and(
          inArray(schema.users.id, selectedIds),
          eq(schema.users.isMock, false),
          isNull(schema.users.deletedAt),
        ),
      );
    if (rows.length !== selectedIds.length) {
      throw new ConflictException('Một hoặc nhiều ứng viên không còn khả dụng.');
    }
    const namesById = new Map(
      rows.map((row) => [
        row.userId,
        row.displayName?.trim() || 'Vận động viên',
      ]),
    );
    return players.map((player) => ({
      userId: player.userId!,
      displayName: namesById.get(player.userId!) ?? 'Vận động viên',
      email: null,
      phone: null,
      role: player.role === 'RESERVE' ? 'RESERVE' : 'MAIN',
    }));
  }

  private async resolveDirectAthletes(
    tx: AppDbOrTx,
    players: AddAthletePlayerDto[],
  ): Promise<ResolvedAddAthlete[]> {
    const normalizedEmails = [
      ...new Set(
        players
          .map((player) => player.email)
          .filter((email): email is string => Boolean(email))
          .map(normalizeEmail),
      ),
    ];
    const accountRows =
      normalizedEmails.length > 0
        ? await tx
            .select({
              userId: schema.users.id,
              email: schema.users.email,
              displayName: schema.profiles.fullName,
            })
            .from(schema.users)
            .leftJoin(
              schema.profiles,
              eq(schema.profiles.userId, schema.users.id),
            )
            .where(
              and(
                inArray(
                  sql<string>`lower(trim(${schema.users.email}))`,
                  normalizedEmails,
                ),
                eq(schema.users.isEmailVerified, true),
                eq(schema.users.isMock, false),
                isNull(schema.users.deletedAt),
              ),
            )
        : [];
    const accountsByEmail = new Map<string, typeof accountRows>();
    for (const account of accountRows) {
      const email = normalizeEmail(account.email);
      accountsByEmail.set(email, [...(accountsByEmail.get(email) ?? []), account]);
    }
    return players.map((player) => {
      const email = player.email ? normalizeEmail(player.email) : null;
      const matches = email ? accountsByEmail.get(email) ?? [] : [];
      const account = matches.length === 1 ? matches[0] : null;
      return {
        userId: account?.userId ?? null,
        displayName:
          account?.displayName?.trim() || player.displayName!.trim(),
        email: account ? null : email,
        phone: account ? null : player.phone?.trim() || null,
        role: player.role === 'RESERVE' ? 'RESERVE' : 'MAIN',
      };
    });
  }

  private assertRosterComposition(
    tournament: AdminTournament,
    matchType: string | null,
    players: ResolvedAddAthlete[],
  ): void {
    const football = resolveFootballTeamConfig(tournament.tournamentConfig);
    if (matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES') {
      if (
        players.length !== 2 ||
        players.some((player) => player.role !== 'MAIN')
      ) {
        throw new BadRequestException('Giải đôi cần đúng hai VĐV chính.');
      }
      return;
    }
    if (football.isTeamSport) {
      const mainCount = players.filter((player) => player.role === 'MAIN').length;
      const reserveCount = players.length - mainCount;
      if (
        mainCount !== football.mainSize ||
        reserveCount > football.maxReserve ||
        players.length > football.maxTotalSize
      ) {
        throw new BadRequestException('Danh sách đội không khớp cấu hình đội bóng.');
      }
      return;
    }
    if (players.length !== 1 || players[0]?.role !== 'MAIN') {
      throw new BadRequestException('Giải đơn cần đúng một VĐV chính.');
    }
  }

  private async assertNoExistingRoster(
    tx: AppDbOrTx,
    tournamentId: string,
    divisionId: string | null,
    players: ResolvedAddAthlete[],
  ): Promise<void> {
    const userIds = players
      .map((player) => player.userId)
      .filter((userId): userId is string => Boolean(userId));
    if (userIds.length === 0) return;
    const existing = await tx
      .select({ userId: schema.tournamentRosters.userId })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.tournamentParticipants,
        eq(
          schema.tournamentParticipants.id,
          schema.tournamentRosters.participantId,
        ),
      )
      .where(
        and(
          eq(schema.tournamentParticipants.tournamentId, tournamentId),
          inArray(schema.tournamentRosters.userId, userIds),
          eq(schema.tournamentRosters.status, 'ACTIVE'),
          inArray(
            schema.tournamentParticipants.teamStatus,
            [...CAPACITY_RESERVING_TEAM_STATUSES],
          ),
          divisionId
            ? eq(
                schema.tournamentParticipants.tournamentDivisionId,
                divisionId,
              )
            : undefined,
        ),
      );
    if (existing.length > 0) {
      throw new ConflictException('Một hoặc nhiều VĐV đã có suất trong giải.');
    }
  }

  private async insertGuestRosters(
    tx: AppDbOrTx,
    participantId: string,
    players: ResolvedAddAthlete[],
  ): Promise<PendingGuestClaim[]> {
    const pending: PendingGuestClaim[] = [];
    for (const player of players) {
      const guestId = randomUUID();
      const claimToken = randomBytes(32).toString('base64url');
      const claimExpiresAt = new Date(Date.now() + GUEST_CLAIM_TTL_MS);
      await tx.insert(schema.tournamentGuestRosters).values({
        id: guestId,
        participantId,
        displayName: player.displayName,
        role: player.role,
        contactEmail: player.email,
        contactPhone: player.phone,
        claimTokenHash: createHash('sha256').update(claimToken).digest('hex'),
        claimExpiresAt,
      });
      pending.push({
        guestId,
        claimToken,
        claimExpiresAt,
        displayName: player.displayName,
        email: player.email,
        phone: player.phone,
        role: player.role,
      });
    }
    return pending;
  }

  private async deliverGuestClaims(
    guests: PendingGuestClaim[],
    tournamentId: string,
    tournamentName: string,
  ) {
    const claims: Array<{
      guestId: string;
      delivery: 'EMAILED' | 'HANDOFF';
      claimToken?: string;
    }> = [];
    for (const guest of guests) {
      const emailed = Boolean(
        guest.email &&
          (await this.rankingConsentService?.sendGuestClaimInvite({
            email: guest.email,
            displayName: guest.displayName,
            tournamentName,
            tournamentId,
            guestId: guest.guestId,
            claimToken: guest.claimToken,
          })),
      );
      claims.push({
        guestId: guest.guestId,
        delivery: emailed ? 'EMAILED' : 'HANDOFF',
        ...(emailed ? {} : { claimToken: guest.claimToken }),
      });
    }
    return claims;
  }

  private async notifyAddedAccounts(
    rosters: Array<{ id: string; userId: string }>,
    tournamentId: string,
    tournamentName: string,
    divisionId: string | null,
  ): Promise<void> {
    for (const roster of rosters) {
      try {
        await this.notificationsService.sendNotification(
          buildParticipantRegistrationSuccessNotification({
            receiverId: roster.userId,
            tournamentId,
            tournamentName,
            divisionId,
          }),
        );
      } catch {
        this.logger.warn(`Không gửi được thông báo roster ${roster.id}.`);
      }
      try {
        await this.rankingConsentService?.sendConfirmationRequest(roster.id);
      } catch {
        this.logger.warn(`Không gửi được yêu cầu consent roster ${roster.id}.`);
      }
    }
  }

  private assertClaimContext(
    context:
      | {
          tournamentId: string;
          participantStatus: string;
          tournamentStatus: string;
          tournamentEndDate: Date | null;
          tournamentDeletedAt: Date | null;
        }
      | undefined,
    tournamentId: string,
  ): asserts context {
    if (
      !context ||
      context.tournamentId !== tournamentId ||
      !CAPACITY_RESERVING_TEAM_STATUSES.some(
        (status) => status === context.participantStatus,
      ) ||
      context.tournamentDeletedAt ||
      context.tournamentStatus === 'COMPLETED' ||
      context.tournamentStatus === 'CANCELLED' ||
      (context.tournamentEndDate && context.tournamentEndDate <= new Date())
    ) {
      throw new ConflictException('Suất tham gia không còn khả dụng.');
    }
  }
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value,
  );
}

function isMatchingClaimHash(storedHash: string, suppliedHash: string): boolean {
  if (!/^[0-9a-f]{64}$/i.test(storedHash)) return false;
  const stored = Buffer.from(storedHash, 'hex');
  const supplied = Buffer.from(suppliedHash, 'hex');
  return stored.length === supplied.length && timingSafeEqual(stored, supplied);
}

