import { Injectable, Inject, Logger, Optional } from '@nestjs/common';
import {
  and,
  eq,
  gt,
  inArray,
  isNull,
  lt,
  notInArray,
  or,
} from 'drizzle-orm';
import { PG_CONNECTION } from '../../../database/database.module';
import type { AppDb } from '../../../database/db.types';
import * as schema from '../../../database/schema';
import { MailService } from '../../../providers/mail/mail.service';
import { CAPACITY_RESERVING_TEAM_STATUSES } from '../utils/tournament-participant-status';

/**
 * Thông báo consent không mang token và chỉ gửi cho roster user đã xác minh email.
 * Claim guest sử dụng một link token riêng, một-lần, gửi trực tiếp về email nhập.
 *
 * Tự động nhắc tối đa 3 lần rồi dừng; không có nút gửi lại phía ban tổ chức.
 */
export const CONSENT_MAX_NOTIFICATIONS = 3;

/** Số giờ chờ trước mỗi lần nhắc, tính từ lần gửi gần nhất. */
export const CONSENT_REMINDER_DELAYS_HOURS = [24, 72] as const;

const FINAL_TOURNAMENT_STATUSES: Record<string, true> = {
  CANCELLED: true,
  COMPLETED: true,
};

type ConsentDispatchKind = 'INITIAL' | 'REMINDER';

interface ConsentScheduleRow {
  attempts: number;
  consentNotifiedAt: Date | null;
  joinedAt: Date | null;
}

@Injectable()
export class RankingConsentService {
  private readonly logger = new Logger(RankingConsentService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    @Optional() private readonly mailService?: MailService,
  ) {}

  private buildFrontendLink(path: string, claimToken?: string): string | null {
    const configuredUrl =
      process.env.FRONTEND_URL ?? 'http://localhost:3001';
    try {
      const base = new URL(configuredUrl);
      if (
        (base.protocol !== 'http:' && base.protocol !== 'https:') ||
        base.username ||
        base.password
      ) {
        return null;
      }

      const link = new URL(path, base.origin);
      if (link.origin !== base.origin) return null;
      if (claimToken) {
        link.hash = new URLSearchParams({ token: claimToken }).toString();
      }
      return link.toString();
    } catch {
      return null;
    }
  }

  /** Gửi ngay cho một roster row cụ thể (dùng khi vừa thêm người). */
  async sendConfirmationRequest(rosterId: string): Promise<boolean> {
    return this.dispatch(rosterId, 'INITIAL');
  }

  async sendGuestClaimInvite(args: {
    email: string;
    displayName: string;
    tournamentName: string;
    tournamentId: string;
    guestId: string;
    claimToken: string;
  }): Promise<boolean> {
    if (!this.mailService) return false;
    const link = this.buildFrontendLink(
      `/tournaments/${encodeURIComponent(args.tournamentId)}/guest-claim/${encodeURIComponent(args.guestId)}`,
      args.claimToken,
    );
    if (!link) return false;

    const tournamentName = args.tournamentName.replace(/[\r\n]+/g, ' ').trim();
    try {
      return await this.mailService.sendMail(
        args.email,
        `[Sporto] Xác nhận suất tham gia: ${tournamentName}`,
        this.buildGuestClaimHtml({
          displayName: args.displayName,
          tournamentName,
          link,
        }),
      );
    } catch {
      this.logger.warn('Gửi mail claim guest thất bại.');
      return false;
    }
  }

  /** Nhắc lại cho những ai đã quá hạn mà chưa xác nhận. */
  async sendDueReminders(): Promise<number> {
    if (!this.mailService) return 0;
    const now = new Date();

    // Keep rows whose notifiedAt is NULL: failed delivery must not consume an
    // attempt or silently end all reminders.
    const due = await this.db
      .select({
        id: schema.tournamentRosters.id,
        attempts: schema.tournamentRosters.consentNotifiedCount,
        consentNotifiedAt: schema.tournamentRosters.consentNotifiedAt,
        joinedAt: schema.tournamentRosters.joinedAt,
      })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.users,
        eq(schema.users.id, schema.tournamentRosters.userId),
      )
      .innerJoin(
        schema.tournamentParticipants,
        eq(
          schema.tournamentParticipants.id,
          schema.tournamentRosters.participantId,
        ),
      )
      .innerJoin(
        schema.tournaments,
        eq(schema.tournaments.id, schema.tournamentParticipants.tournamentId),
      )
      .where(
        and(
          isNull(schema.tournamentRosters.rankingConsentAt),
          eq(schema.tournamentRosters.status, 'ACTIVE'),
          inArray(
            schema.tournamentParticipants.teamStatus,
            [...CAPACITY_RESERVING_TEAM_STATUSES],
          ),
          eq(schema.users.isEmailVerified, true),
          isNull(schema.users.deletedAt),
          eq(schema.tournaments.isRanked, true),
          isNull(schema.tournaments.deletedAt),
          notInArray(schema.tournaments.status, [
            'COMPLETED',
            'CANCELLED',
          ]),
          or(
            isNull(schema.tournaments.endDate),
            gt(schema.tournaments.endDate, now),
          ),
          lt(
            schema.tournamentRosters.consentNotifiedCount,
            CONSENT_MAX_NOTIFICATIONS,
          ),
        ),
      );

    let sent = 0;
    for (const row of due) {
      if (!this.isReminderDue(row, now)) continue;
      if (await this.dispatch(row.id, 'REMINDER')) sent += 1;
    }
    return sent;
  }

  private isReminderDue(row: ConsentScheduleRow, now: Date): boolean {
    if (row.attempts >= CONSENT_MAX_NOTIFICATIONS) return false;
    const anchor = row.consentNotifiedAt ?? row.joinedAt;
    if (!anchor) return false;
    const delayHours =
      CONSENT_REMINDER_DELAYS_HOURS[
        Math.min(
          Math.max(row.attempts - 1, 0),
          CONSENT_REMINDER_DELAYS_HOURS.length - 1,
        )
      ];
    return now.getTime() - new Date(anchor).getTime() >= delayHours * 3_600_000;
  }

  /**
   * Gửi 1 mail và ghi nhận số lần đã gửi.
   *
   * Chỉ tăng bộ đếm khi gửi THÀNH CÔNG — nếu không, một hệ thống mail hỏng sẽ đốt
   * hết 3 lượt nhắc rồi im lặng, biến "chưa gửi được" thành "đã bỏ qua".
   */
  private async dispatch(
    rosterId: string,
    kind: ConsentDispatchKind,
  ): Promise<boolean> {
    if (!this.mailService) return false;

    try {
      return await this.db.transaction(async (tx) => {
        const [row] = await tx
          .select({
            userEmail: schema.users.email,
            userEmailVerified: schema.users.isEmailVerified,
            userDeletedAt: schema.users.deletedAt,
            participantName: schema.tournamentParticipants.teamName,
            participantStatus: schema.tournamentParticipants.teamStatus,
            tournamentName: schema.tournaments.name,
            tournamentId: schema.tournaments.id,
            tournamentStatus: schema.tournaments.status,
            tournamentEndDate: schema.tournaments.endDate,
            tournamentDeletedAt: schema.tournaments.deletedAt,
            isRanked: schema.tournaments.isRanked,
            attempts: schema.tournamentRosters.consentNotifiedCount,
            consentNotifiedAt: schema.tournamentRosters.consentNotifiedAt,
            consentedAt: schema.tournamentRosters.rankingConsentAt,
            joinedAt: schema.tournamentRosters.joinedAt,
            rosterStatus: schema.tournamentRosters.status,
          })
          .from(schema.tournamentRosters)
          .innerJoin(
            schema.users,
            eq(schema.users.id, schema.tournamentRosters.userId),
          )
          .innerJoin(
            schema.tournamentParticipants,
            eq(
              schema.tournamentParticipants.id,
              schema.tournamentRosters.participantId,
            ),
          )
          .innerJoin(
            schema.tournaments,
            eq(
              schema.tournaments.id,
              schema.tournamentParticipants.tournamentId,
            ),
          )
          .where(eq(schema.tournamentRosters.id, rosterId))
          .for('update')
          .limit(1);

        const now = new Date();
        if (
          !row ||
          !row.userEmail ||
          !row.userEmailVerified ||
          row.userDeletedAt ||
          !row.isRanked ||
          row.consentedAt ||
          row.rosterStatus !== 'ACTIVE' ||
          !CAPACITY_RESERVING_TEAM_STATUSES.some(
            (status) => status === row.participantStatus,
          ) ||
          row.tournamentDeletedAt ||
          FINAL_TOURNAMENT_STATUSES[row.tournamentStatus] ||
          (row.tournamentEndDate && row.tournamentEndDate <= now) ||
          row.attempts >= CONSENT_MAX_NOTIFICATIONS ||
          (kind === 'INITIAL' && row.attempts !== 0) ||
          (kind === 'REMINDER' && !this.isReminderDue(row, now))
        ) {
          return false;
        }

        const link = this.buildFrontendLink(
          `/tournaments/${encodeURIComponent(row.tournamentId)}`,
        );
        if (!link) return false;
        const isReminder = kind === 'REMINDER';
        const subject = isReminder
          ? 'Nhắc xác nhận tham gia giải đấu'
          : 'Xác nhận tham gia giải đấu';
        const tournamentName = row.tournamentName
          .replace(/[\r\n]+/g, ' ')
          .trim();
        const sent = await this.mailService.sendMail(
          row.userEmail,
          `[Sporto] ${subject}: ${tournamentName}`,
          this.buildHtml({
            participantName: row.participantName,
            tournamentName,
            link,
            isReminder,
          }),
        );
        if (!sent) return false;

        await tx
          .update(schema.tournamentRosters)
          .set({
            consentNotifiedAt: now,
            consentNotifiedCount: row.attempts + 1,
          })
          .where(eq(schema.tournamentRosters.id, rosterId));
        return true;
      });
    } catch {
      this.logger.warn(`Gửi mail xác nhận thất bại cho roster ${rosterId}.`);
      return false;
    }
  }

  private buildHtml(args: {
