  }

  private buildGuestClaimHtml(args: {
    displayName: string;
    tournamentName: string;
    link: string;
  }): string {
    return `
      <div style="font-family: system-ui, -apple-system, sans-serif; max-width: 560px;">
        <p>Xin chào ${escapeHtml(args.displayName)},</p>
        <p>Ban tổ chức đã ghi danh bạn vào giải <strong>${escapeHtml(args.tournamentName)}</strong>.</p>
        <p>Đăng nhập bằng email này để nhận suất tham gia:</p>
        <a href="${escapeHtml(args.link)}">Nhận suất tham gia</a>
      </div>
    `;
  }
}

const HTML_ESCAPE_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => HTML_ESCAPE_MAP[character]);
}
